repo.readings.py:
"""Reading records."""


class Reading:
    def __init__(self, sensor, level):
        self.sensor = sensor
        self.level = level

    def __repr__(self):
        return "Reading(%r, %r)" % (self.sensor, self.level)


ROWS = [('east', 30), ('east', 13), ('east', 10), ('north', 47), ('south', 37)]


def load_readings():
    """Yield the stored readings one at a time."""
    for sensor, level in ROWS:
        yield Reading(sensor, level)

repo.labels.py:
"""Labels for readings."""


def label_readings(names, readings):
    """Return (lookup, lines): a name -> level dict and one 'name: level' line per reading."""
    pairs = zip(names, (x.level for x in readings))
    lookup = dict(pairs)
    lines = ["%s: %s" % (name, value) for name, value in pairs]
    return lookup, lines


def name_list(names):
    """Return the names joined by commas."""
    return ", ".join(names)

